
// ─── App state initialization ───────────────────────────────────────
//
// On startup, try to restore from localStorage. If we have a valid saved
// blob, use it; otherwise initialize defaults from makeDays() and run the
// one-time catalog migration. Either path ends with DAYS and EXERCISES
// fully populated and consistent.

let DAYS;
// HISTORY: the permanent log of completed sessions (SessionRecords). This is
// the data layer's spine — History/Progress/PRs all read from it. It is
// append-mostly: a record is added when a session is logged, and records are
// editable/deletable but never silently mutated.
let HISTORY=[];
let _wsInjectPlanOnFreshStart=false;
const _wsLoadedBlob=wsPersistLoad();

// Numeric input UX: select-all on focus so the first keystroke replaces the
// existing value (fixes leading-zero "010" when default is 0, and lets a real
// saved value like 15 be typed-over or tap-again-to-edit). One delegated
// listener covers all numeric fields app-wide (set weight/reps, rest, duration,
// distance, interval times). Text fields (titles, cues, search) are excluded.
document.addEventListener('focusin',(e)=>{
  const el=e.target;
  if(!el || el.tagName!=='INPUT') return;
  const mode=(el.getAttribute('inputmode')||'').toLowerCase();
  const isNumeric = mode==='numeric' || mode==='decimal' || el.type==='number';
  if(!isNumeric) return;
  // defer so the browser's own focus caret placement doesn't override us
  setTimeout(()=>{ try{ el.select(); }catch(_){} }, 0);
});
if(_wsLoadedBlob){
  // Catalog and days are already migrated in the saved blob — just apply.
  DAYS=_wsLoadedBlob.days;
  // EXERCISES gets reassigned by wsPersistApply, but we need it before that.
  // Actually wsPersistApply does everything; just call it and we're done.
  wsPersistApply(_wsLoadedBlob);
  if(Array.isArray(_wsLoadedBlob.history)) HISTORY=_wsLoadedBlob.history;
  _wsLoadedFromStorage=true;
} else {
  // Fresh start: build days from the static template and run migration to
  // stamp exIds and extend the catalog with anything not yet known.
  DAYS=makeDays();
  wsMigrateDayInstances(DAYS);
  _wsInjectPlanOnFreshStart=true;
  // Save the initial state so next load uses persistence.
  // Defer until after script init so any later setup completes first.
  setTimeout(()=>wsPersistFlush(),0);
}
// Items-model migration runs on both paths: it's idempotent and only adds
// d.items[] where it doesn't already exist (or extends it where instances
// were added via the legacy arrays). Iteration 1 of mixed-day support.
wsMigrateToItemsModel(DAYS);

// DEV: demo-history seeding. OFF for real use — this is a daily driver, and
// auto-injecting fake sessions into the permanent HISTORY log on an empty
// start (post-reset, new device) would silently pollute real data. To demo
// the data features, call wsInjectSeedHistory(8) from the console; seeded
// records carry r.seeded and are removable via wsClearSeedHistory().
