// Inject the modeled personal-plan history (Phase D). Sets bodyweight to 73kg
// and loads ~8 weeks of late-April→mid-June sessions with slow progression and
// two breaks. Runs once on a fresh start; idempotent via the seeded flag.
function wsInjectPlanHistory(){
  try{
    // Don't clobber real logged sessions — only inject into an empty history.
    if(Array.isArray(HISTORY) && HISTORY.length>0) return;
    // Defence in depth: once the user has deliberately started empty, an empty
    // HISTORY is the DESIRED state, not a fresh install. Without this the demo
    // sessions walked straight back in after "start empty".
    try{ if(typeof settings==='object'&&settings&&settings._planHistoryInjected) return; }catch(_){}
    // ensure bodyweight profile has 73kg as the current reading
    if(!settings.profile) settings.profile={};
    if(!Array.isArray(settings.profile.bodyweight) || !settings.profile.bodyweight.length){
      settings.profile.bodyweight=[{value:73, date:new Date('2025-04-20').toISOString()}];
    }
    HISTORY = JSON.parse(JSON.stringify(WS_PLAN_HISTORY));
    wsPersistSave();
    if(WS_DEBUG_LOG && console&&console.log) console.log('[Gains] Injected',HISTORY.length,'plan-history sessions.');
    if(typeof wsRender==='function') wsRender();
  }catch(e){ if(console&&console.warn) console.warn('Plan history inject failed:',e&&e.message); }
}
